import sys
import re
from bs4 import BeautifulSoup

def clean_html(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            html = f.read()
    except Exception as e:
        return

    soup = BeautifulSoup(html, 'html.parser')

    # 1. Remove all script tags directly
    for script in soup.find_all('script'):
        script.decompose()

    # 2. Iteratively inspect elements for malicious attributes
    for tag in soup.find_all(True):
        for attr in list(tag.attrs.keys()):
            attr_lower = attr.lower()

            # Strip event handlers entirely
            if attr_lower.startswith('on'):
                del tag[attr]
                continue

            val = tag.attrs[attr]
            if val is None:
                continue

            val_str = ' '.join(val) if isinstance(val, list) else str(val)

            # Pre-clean string by stripping control characters and spaces for URI checks
            cleaned = re.sub(r'[\x00-\x20\x7F-\x9F]', '', val_str).lower()

            # Prevent JS injections in inline style tags (e.g., CSS expressions)
            if attr_lower == 'style':
                if 'javascript:' in cleaned or 'expression(' in cleaned:
                    del tag[attr]
                continue

            # Standard javascript:/vbscript: URI prefix checks
            if cleaned.startswith('javascript:') or cleaned.startswith('vbscript:'):
                del tag[attr]
                continue

            # Meta refresh injection checks
            if tag.name and tag.name.lower() == 'meta' and attr_lower == 'content':
                if 'url=javascript:' in cleaned or 'url=vbscript:' in cleaned:
                    del tag[attr]
                continue

            # Simple validation to block JS execution inside iframe srcdoc elements
            if attr_lower == 'srcdoc':
                if '<script' in cleaned or 'javascript:' in cleaned or 'vbscript:' in cleaned:
                    del tag[attr]
                continue

    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(str(soup))

if __name__ == '__main__':
    if len(sys.argv) > 1:
        clean_html(sys.argv[1])
