import os
import pty
import time
import threading
from base_terminal import BaseTerminal

class HeadlessTerminal(BaseTerminal):
    def __init__(self):
        self.pid, self.fd = pty.fork()
        if self.pid == 0:
            os.environ["TERM"] = "xterm"
            os.execv('/bin/bash', ['bash', '-i'])
        else:
            self.thread = threading.Thread(target=self._read_loop, daemon=True)
            self.thread.start()
            time.sleep(0.5)

    def _read_loop(self):
        while True:
            try:
                data = os.read(self.fd, 4096)
                if not data:
                    break
            except OSError:
                break

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        os.write(self.fd, keystrokes.encode('utf-8'))
        if wait_sec > 0:
            time.sleep(wait_sec)
