import torch
import torch.nn as nn
import torch.distributed as dist

class _GatherFromModelParallelRegion(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input_):
        world_size = dist.get_world_size() if dist.is_initialized() else 1
        if world_size == 1:
            return input_

        ctx.world_size = world_size
        ctx.rank = dist.get_rank()

        input_ = input_.contiguous()
        tensor_list = [torch.empty_like(input_) for _ in range(world_size)]
        dist.all_gather(tensor_list, input_)
        output = torch.cat(tensor_list, dim=-1)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        world_size = getattr(ctx, 'world_size', 1)
        if world_size == 1:
            return grad_output

        rank = ctx.rank
        chunks = torch.chunk(grad_output, world_size, dim=-1)
        return chunks[rank].contiguous()

class _ReduceFromModelParallelRegion(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input_):
        world_size = dist.get_world_size() if dist.is_initialized() else 1
        if world_size == 1:
            return input_

        input_ = input_.contiguous()
        dist.all_reduce(input_)
        return input_

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output

class ColumnParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        world_size = dist.get_world_size() if dist.is_initialized() else 1
        rank = dist.get_rank() if dist.is_initialized() else 0

        self.in_features = in_features
        self.out_features = out_features

        partition_weight = torch.chunk(master_weight, world_size, dim=0)[rank].contiguous()
        self.weight = nn.Parameter(partition_weight.clone().detach())

        if bias:
            self.bias = nn.Parameter(torch.zeros(partition_weight.size(0)))
        else:
            self.register_parameter('bias', None)

    def forward(self, input):
        output_parallel = torch.nn.functional.linear(input, self.weight, self.bias)
        output = _GatherFromModelParallelRegion.apply(output_parallel)
        return output

class RowParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
